import { theme } from '../../../../theme';
import { AVATAR_BACKGROUND_TOKEN_MAP } from '../Avatar.constants';

export const resolveBackgroundColor = (
  background: string | undefined,
  disabled: boolean,
): string => {
  if (disabled) {
    return theme.colors.interfaceSurfacePrimary;
  }

  if (!background) {
    return theme.colors.brandPrimaryBasis;
  }

  const mappedToken = AVATAR_BACKGROUND_TOKEN_MAP[background] ?? background;
  const color = theme.colors[mappedToken as keyof typeof theme.colors];

  return typeof color === 'string' ? color : theme.colors.brandPrimaryBasis;
};
